count='def count_full(scores):\n    total = 0\n    for row in scores:\n        for value in row:\n            if value == 12:\n                total += 1\n    return total'
add(14,'b',8,4,'Construct','Construct an algorithm that determines and outputs the number of times the highest attainable score was awarded in this competition.',ctx14,[15],'Nested traversal,compare10,increment initialized counter,output.','B',['B2.2.2','B2.3.3'],'Nested array processing converted to general Python 2D lists.','A robotics event records judges’ integer scores from 0 to 12 in a 2D list scores. Construct a Python function returning the total number of 12s across all rows.',count,'Initializes count0.|Traverses every row and every element.|Tests each value==12.|Increments correctly and returns final count.',code=count,test='Executed on empty list,empty rows,zero/full scores and mixed matrix; results checked.')
score='def final_scores(names, scores):\n    results = []\n    for i in range(len(scores)):\n        row = scores[i]\n        high = low = row[0]\n        total = 0\n        for value in row:\n            total += value\n            if value > high:\n                high = value\n            if value < low:\n                low = value\n        final = (total - high - low) / (len(row) - 2)\n        results.append((names[i], final))\n    return results'
add(14,'c',8,10,'Construct','Construct an algorithm in pseudocode to output the name and the final score for every competitor.',ctx14,[16,17,18],'Process all competitors,initialize extrema/sum,scan scores,remove exactly one max/min,divide6,output paired names.','B',['B2.2.2','B2.3.3','B2.3.2'],'Preserve nested traversal/extrema/mean challenge in Python; makes conditions/data domain explicit.','A design contest stores entrant names in names and corresponding judge scores in scores. Each row has at least 3 numeric scores. Construct Python function final_scores(names,scores) returning (name, adjusted_mean) pairs. For each row remove exactly one occurrence of its largest and one of its smallest score before averaging. Use explicit loops to calculate totals/extrema rather than sum,min,max or sorting. Assume names and scores have equal length.',score,'Iterates each entrant.|Pairs same indexed name and score row.|Initializes row total0.|Initializes high/low from row value.|Traverses every score.|Accumulates total.|Updates highest correctly.|Updates lowest correctly,including equal-score cases.|Subtracts exactly one highest and one lowest and divides by len(row)-2.|Returns all correct name/result pairs.',code=score,test='Executed on duplicate extrema,all-equal scores,negative values,3-score rows and multiple entrants. Cross-checked with independently sorted row[1:-1] mean.',difficulty='high',issues=['Source MS uses MARKS while paper uses SCORES; adapted variables made consistent. Source sorting sample loop bound requires independent verification; adaptation uses independently executed linear scan.'])
